-- 1. DELETE EXISTING DUPLICATE CHECKLIST DATA & ORPHAN RESULTS
DELETE FROM project_checklist_results;
DELETE FROM checklist_items;
DELETE FROM checklist_categories;

-- 2. INSERT 69 UNIQUE CATEGORIES

-- 3. INSERT 1,260 UNIQUE CHECKLIST ITEMS













-- 4. RE-ATTACH RESULT PLACEHOLDERS TO EXISTING PROJECTS
SELECT 
  'res-' || p.id || '-' || ci.id AS id,
  p.id AS project_id,
  ci.id AS item_id,
  'not_tested' AS status,
  p.lead_tester AS tester_name,
  CURRENT_TIMESTAMP AS updated_at
FROM projects p
CROSS JOIN checklist_items ci
ON CONFLICT (project_id, item_id) DO NOTHING;
