INSERT INTO checklist_items (id, category_id, code, title, description, verification_guide, criticality, priority, section_group, order_index) VALUES
  ('item-sec-001', 'cat-1-secrets-api-keys-configuration', 'SEC-001', 'No secrets in source code', 'API keys, database passwords, OAuth secrets, signing keys, private certificates, webhook secrets, encryption keys, and service credentials must never be hardcoded.', 'No secrets in source code: API keys, database passwords, OAuth secrets, signing keys, private certificates, webhook secrets, encryption keys, and service credentials must never be hardcoded.', 'Critical', 'P0', 'Production & Security Controls', 1),
  ('item-sec-002', 'cat-1-secrets-api-keys-configuration', 'SEC-002', 'No secrets in client bundles', 'anything shipped to the browser must be assumed public.', 'No secrets in client bundles: anything shipped to the browser must be assumed public.', 'Critical', 'P0', 'Production & Security Controls', 2),
  ('item-sec-003', 'cat-1-secrets-api-keys-configuration', 'SEC-003', 'No secrets in Git history', 'scan current files and Git history for leaked credentials.', 'No secrets in Git history: scan current files and Git history for leaked credentials.', 'Critical', 'P0', 'Production & Security Controls', 3),
  ('item-sec-004', 'cat-1-secrets-api-keys-configuration', 'SEC-004', 'Purge compromised Git secrets', 'removing a secret from the latest commit is not enough; rotate/revoke the exposed credential.', 'Purge compromised Git secrets: removing a secret from the latest commit is not enough; rotate/revoke the exposed credential.', 'Critical', 'P0', 'Production & Security Controls', 4),
  ('item-sec-005', 'cat-1-secrets-api-keys-configuration', 'SEC-005', 'Rotate every previously exposed credential', 'treat leaked secrets as compromised even if the repository was private.', 'Rotate every previously exposed credential: treat leaked secrets as compromised even if the repository was private.', 'Critical', 'P0', 'Production & Security Controls', 5),
  ('item-sec-006', 'cat-1-secrets-api-keys-configuration', 'SEC-006', 'Use environment-based configuration', 'separate development, staging, and production configuration.', 'Use environment-based configuration: separate development, staging, and production configuration.', 'Critical', 'P0', 'Production & Security Controls', 6),
  ('item-sec-007', 'cat-1-secrets-api-keys-configuration', 'SEC-007', 'Use a dedicated secret manager where appropriate', 'do not turn .env files into a production secret-management system.', 'Use a dedicated secret manager where appropriate: do not turn .env files into a production secret-management system.', 'Critical', 'P0', 'Production & Security Controls', 7),
  ('item-sec-008', 'cat-1-secrets-api-keys-configuration', 'SEC-008', 'Separate production credentials from development credentials', 'a developer machine should not automatically have production-level secrets.', 'Separate production credentials from development credentials: a developer machine should not automatically have production-level secrets.', 'Critical', 'P0', 'Production & Security Controls', 8),
  ('item-sec-009', 'cat-1-secrets-api-keys-configuration', 'SEC-009', 'Minimize credential privileges', 'each key should have only the permissions required by its workload.', 'Minimize credential privileges: each key should have only the permissions required by its workload.', 'Critical', 'P0', 'Production & Security Controls', 9),
  ('item-sec-010', 'cat-1-secrets-api-keys-configuration', 'SEC-010', 'Define a secret rotation procedure', 'know how to revoke and replace credentials without taking the system down.', 'Define a secret rotation procedure: know how to revoke and replace credentials without taking the system down.', 'Critical', 'P0', 'Production & Security Controls', 10),
  ('item-sec-011', 'cat-1-secrets-api-keys-configuration', 'SEC-011', 'Audit server environment variables', 'remove unused variables and legacy credentials.', 'Audit server environment variables: remove unused variables and legacy credentials.', 'Critical', 'P0', 'Production & Security Controls', 11),
  ('item-sec-012', 'cat-1-secrets-api-keys-configuration', 'SEC-012', 'Check CI/CD logs for secret leakage', 'secrets must not appear in build logs, error output, or test reports.', 'Check CI/CD logs for secret leakage: secrets must not appear in build logs, error output, or test reports.', 'Critical', 'P0', 'Production & Security Controls', 12),
  ('item-sec-013', 'cat-1-secrets-api-keys-configuration', 'SEC-013', 'Check crash reports for secrets', 'exceptions and serialized request objects must not contain credentials or tokens.', 'Check crash reports for secrets: exceptions and serialized request objects must not contain credentials or tokens.', 'Critical', 'P0', 'Production & Security Controls', 13),
  ('item-sec-014', 'cat-1-secrets-api-keys-configuration', 'SEC-014', 'Check Docker/container images for secrets', 'secrets must not be baked into layers or image metadata.', 'Check Docker/container images for secrets: secrets must not be baked into layers or image metadata.', 'Critical', 'P0', 'Production & Security Controls', 14),
  ('item-sec-015', 'cat-1-secrets-api-keys-configuration', 'SEC-015', 'Document which variables are public and which are secret', 'especially important for frameworks such as Next.js where client-exposed environment variables are intentional.', 'Document which variables are public and which are secret: especially important for frameworks such as Next.js where client-exposed environment variables are intentional.', 'Critical', 'P0', 'Production & Security Controls', 15),
  ('item-sec-016', 'cat-1-secrets-api-keys-configuration', 'SEC-016', 'Use the publishable/anon key only where client exposure is intended', 'this key is not a substitute for authorization.', 'Use the publishable/anon key only where client exposure is intended: this key is not a substitute for authorization.', 'Critical', 'P0', 'Production & Security Controls', 16),
  ('item-sec-017', 'cat-1-secrets-api-keys-configuration', 'SEC-017', 'Never expose the Supabase secret/service-role key to the browser', 'these elevated keys can bypass RLS.', 'Never expose the Supabase secret/service-role key to the browser: these elevated keys can bypass RLS.', 'Critical', 'P0', 'Production & Security Controls', 17),
  ('item-sec-018', 'cat-1-secrets-api-keys-configuration', 'SEC-018', 'Treat RLS as the actual database security boundary', 'a public key is acceptable only when database policies are correct.', 'Treat RLS as the actual database security boundary: a public key is acceptable only when database policies are correct.', 'Critical', 'P0', 'Production & Security Controls', 18),
  ('item-sec-019', 'cat-1-secrets-api-keys-configuration', 'SEC-019', 'Audit every database object reachable through the Data API', 'public schema objects can have broader default privileges than intended.', 'Audit every database object reachable through the Data API: public schema objects can have broader default privileges than intended.', 'Critical', 'P0', 'Production & Security Controls', 19),
  ('item-auth-001', 'cat-2-authentication', 'AUTH-001', 'Authentication is enforced server-side', 'never trust frontend route guards as the security boundary.', 'Authentication is enforced server-side: never trust frontend route guards as the security boundary.', 'Critical', 'P0', 'Production & Security Controls', 20),
  ('item-auth-002', 'cat-2-authentication', 'AUTH-002', 'Every protected API endpoint verifies authentication', 'do not rely on the UI hiding access.', 'Every protected API endpoint verifies authentication: do not rely on the UI hiding access.', 'Critical', 'P0', 'Production & Security Controls', 21),
  ('item-auth-003', 'cat-2-authentication', 'AUTH-003', 'Every server action verifies authentication', 'server actions are backend entry points.', 'Every server action verifies authentication: server actions are backend entry points.', 'Critical', 'P0', 'Production & Security Controls', 22),
  ('item-auth-004', 'cat-2-authentication', 'AUTH-004', 'Every background job verifies authorization', 'never assume the caller was authenticated when the job was created.', 'Every background job verifies authorization: never assume the caller was authenticated when the job was created.', 'Critical', 'P0', 'Production & Security Controls', 23),
  ('item-auth-005', 'cat-2-authentication', 'AUTH-005', 'Password hashes use a password-specific hashing algorithm', 'never store plaintext or reversibly encrypted passwords.', 'Password hashes use a password-specific hashing algorithm: never store plaintext or reversibly encrypted passwords.', 'Critical', 'P0', 'Production & Security Controls', 24),
  ('item-auth-006', 'cat-2-authentication', 'AUTH-006', 'Use a modern password hashing configuration', 'Argon2id is preferred when available; bcrypt/scrypt can be appropriate depending on the environment.', 'Use a modern password hashing configuration: Argon2id is preferred when available; bcrypt/scrypt can be appropriate depending on the environment.', 'Critical', 'P0', 'Production & Security Controls', 25),
  ('item-auth-007', 'cat-2-authentication', 'AUTH-007', 'Passwords never appear in logs or telemetry.', 'Passwords never appear in logs or telemetry.', 'Verify and test: Passwords never appear in logs or telemetry.', 'Critical', 'P0', 'Production & Security Controls', 26),
  ('item-auth-008', 'cat-2-authentication', 'AUTH-008', 'Login attempts are rate limited.', 'Login attempts are rate limited.', 'Verify and test: Login attempts are rate limited.', 'Critical', 'P0', 'Production & Security Controls', 27),
  ('item-auth-009', 'cat-2-authentication', 'AUTH-009', 'Credential stuffing protection is implemented.', 'Credential stuffing protection is implemented.', 'Verify and test: Credential stuffing protection is implemented.', 'Critical', 'P0', 'Production & Security Controls', 28),
  ('item-auth-010', 'cat-2-authentication', 'AUTH-010', 'Bot protection is applied to high-risk authentication flows.', 'Bot protection is applied to high-risk authentication flows.', 'Verify and test: Bot protection is applied to high-risk authentication flows.', 'Critical', 'P0', 'Production & Security Controls', 29),
  ('item-auth-011', 'cat-2-authentication', 'AUTH-011', 'Email verification is implemented where required.', 'Email verification is implemented where required.', 'Verify and test: Email verification is implemented where required.', 'Critical', 'P0', 'Production & Security Controls', 30),
  ('item-auth-012', 'cat-2-authentication', 'AUTH-012', 'Password reset tokens are cryptographically random.', 'Password reset tokens are cryptographically random.', 'Verify and test: Password reset tokens are cryptographically random.', 'Critical', 'P0', 'Production & Security Controls', 31),
  ('item-auth-013', 'cat-2-authentication', 'AUTH-013', 'Password reset links expire.', 'Password reset links expire.', 'Verify and test: Password reset links expire.', 'Critical', 'P0', 'Production & Security Controls', 32),
  ('item-auth-014', 'cat-2-authentication', 'AUTH-014', 'Password reset tokens are single-use.', 'Password reset tokens are single-use.', 'Verify and test: Password reset tokens are single-use.', 'Critical', 'P0', 'Production & Security Controls', 33),
  ('item-auth-015', 'cat-2-authentication', 'AUTH-015', 'Password reset invalidates relevant sessions when appropriate.', 'Password reset invalidates relevant sessions when appropriate.', 'Verify and test: Password reset invalidates relevant sessions when appropriate.', 'Critical', 'P0', 'Production & Security Controls', 34),
  ('item-auth-016', 'cat-2-authentication', 'AUTH-016', 'Changing a password invalidates old sessions when appropriate.', 'Changing a password invalidates old sessions when appropriate.', 'Verify and test: Changing a password invalidates old sessions when appropriate.', 'Critical', 'P0', 'Production & Security Controls', 35),
  ('item-auth-017', 'cat-2-authentication', 'AUTH-017', 'Session revocation exists', 'users/admins can invalidate active sessions.', 'Session revocation exists: users/admins can invalidate active sessions.', 'Critical', 'P0', 'Production & Security Controls', 36),
  ('item-auth-018', 'cat-2-authentication', 'AUTH-018', 'Account recovery cannot bypass MFA/security controls.', 'Account recovery cannot bypass MFA/security controls.', 'Verify and test: Account recovery cannot bypass MFA/security controls.', 'Critical', 'P0', 'Production & Security Controls', 37),
  ('item-auth-019', 'cat-2-authentication', 'AUTH-019', 'MFA exists for privileged/admin accounts.', 'MFA exists for privileged/admin accounts.', 'Verify and test: MFA exists for privileged/admin accounts.', 'Critical', 'P0', 'Production & Security Controls', 38),
  ('item-auth-020', 'cat-2-authentication', 'AUTH-020', 'Sensitive actions require recent authentication where appropriate', 'changing email, password, payment information, organization ownership, etc.', 'Sensitive actions require recent authentication where appropriate: changing email, password, payment information, organization ownership, etc.', 'Critical', 'P0', 'Production & Security Controls', 39),
  ('item-auth-021', 'cat-2-authentication', 'AUTH-021', 'User enumeration is controlled', 'login/reset flows should not unnecessarily reveal whether an account exists.', 'User enumeration is controlled: login/reset flows should not unnecessarily reveal whether an account exists.', 'Critical', 'P0', 'Production & Security Controls', 40),
  ('item-auth-022', 'cat-2-authentication', 'AUTH-022', 'OAuth/OIDC redirect URLs are allowlisted.', 'OAuth/OIDC redirect URLs are allowlisted.', 'Verify and test: OAuth/OIDC redirect URLs are allowlisted.', 'Critical', 'P0', 'Production & Security Controls', 41),
  ('item-auth-023', 'cat-2-authentication', 'AUTH-023', 'OAuth state/PKCE protections are correctly implemented.', 'OAuth state/PKCE protections are correctly implemented.', 'Verify and test: OAuth state/PKCE protections are correctly implemented.', 'Critical', 'P0', 'Production & Security Controls', 42),
  ('item-auth-024', 'cat-2-authentication', 'AUTH-024', 'Authentication tokens have appropriate expiration and rotation behavior.', 'Authentication tokens have appropriate expiration and rotation behavior.', 'Verify and test: Authentication tokens have appropriate expiration and rotation behavior.', 'Critical', 'P0', 'Production & Security Controls', 43),
  ('item-sess-001', 'cat-3-session-cookie-security', 'SESS-001', 'Session cookies use Secure', 'cookies are sent only over HTTPS.', 'Session cookies use Secure: cookies are sent only over HTTPS.', 'Low', 'P3', 'Production & Security Controls', 44),
  ('item-sess-002', 'cat-3-session-cookie-security', 'SESS-002', 'Session cookies use HttpOnly', 'JavaScript cannot read sensitive authentication cookies.', 'Session cookies use HttpOnly: JavaScript cannot read sensitive authentication cookies.', 'Low', 'P3', 'Production & Security Controls', 45),
  ('item-sess-003', 'cat-3-session-cookie-security', 'SESS-003', 'SameSite is explicitly chosen', 'do not rely on accidental browser defaults for security-sensitive authentication.', 'SameSite is explicitly chosen: do not rely on accidental browser defaults for security-sensitive authentication.', 'Low', 'P3', 'Production & Security Controls', 46),
  ('item-sess-004', 'cat-3-session-cookie-security', 'SESS-004', 'Cookie domain is as narrow as practical.', 'Cookie domain is as narrow as practical.', 'Verify and test: Cookie domain is as narrow as practical.', 'Low', 'P3', 'Production & Security Controls', 47),
  ('item-sess-005', 'cat-3-session-cookie-security', 'SESS-005', 'Cookie path is as narrow as practical.', 'Cookie path is as narrow as practical.', 'Verify and test: Cookie path is as narrow as practical.', 'Low', 'P3', 'Production & Security Controls', 48),
  ('item-sess-006', 'cat-3-session-cookie-security', 'SESS-006', 'Use Host- cookies where appropriate for host-only session cookies.', 'Use Host- cookies where appropriate for host-only session cookies.', 'Verify and test: Use Host- cookies where appropriate for host-only session cookies.', 'Low', 'P3', 'Production & Security Controls', 49),
